// AxISA v2.0 step 5 (see sw/su3mul_test.axasm and docs/ISA.md's SU3MUL
// section): bit-exact psi' = U*psi for real SU(3) matrices, chaining,
// in-place, the highest legal matrix base, 4 traps, and 133 cycles per
// SU3MUL. GENERATED by tools/gen_su3mul_test.py.
`timescale 1ns/1ps
`ifndef INSTR_HEX
`define INSTR_HEX "sw/su3mul_test.hex"
`endif

module tb_su3mul;
    reg clk, reset;
    integer errors;
    integer max_cycles;
    integer cycle_count;

    wire halted;
    wire [31:0] tohost_value;
    wire        bus_req, bus_mem_write, bus_mem_unsigned, bus_grant;
    wire [31:0] bus_addr, bus_write_data, bus_read_data;
    wire [1:0]  bus_mem_size;
    wire        uart_tx_valid;
    wire [7:0]  uart_tx_data;

    cpu_core #(.INSTR_MEM_WORDS(1024), .INSTR_INIT_FILE(`INSTR_HEX)) dut (
        .clk(clk), .reset(reset), .halted(halted), .tohost_value(tohost_value),
        .irq_in(1'b0),
        .bus_req(bus_req), .bus_addr(bus_addr), .bus_write_data(bus_write_data),
        .bus_mem_write(bus_mem_write), .bus_mem_size(bus_mem_size), .bus_mem_unsigned(bus_mem_unsigned),
        .bus_grant(1'b0), .bus_read_data(32'b0),
        .uart_tx_valid(uart_tx_valid), .uart_tx_data(uart_tx_data),
        .uart_rx_data_in(8'b0), .uart_rx_ready_in(1'b0), .uart_rx_ack()
    );

    always #5 clk = ~clk;

    // cycles each SU3MUL keeps is_su3mul high (legal ones only: the
    // illegal ones trap on their first cycle and are counted as 1s)
    integer lat [0:15];
    integer n_lat, cur;
    initial begin n_lat = 0; cur = 0; end
    always @(posedge clk) begin
        if (!reset && dut.is_su3mul) cur = cur + 1;
        else if (cur != 0) begin
            if (n_lat < 16) lat[n_lat] = cur;
            n_lat = n_lat + 1;
            cur = 0;
        end
    end

    task check(input [31:0] got, input [31:0] expected, input [48*8-1:0] name);
        begin
            if (got !== expected) begin
                $display("FAIL: %0s got=%0d (0x%h) expected=%0d (0x%h)", name, got, got, expected, expected);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s = %0d (0x%h)", name, got, got);
            end
        end
    endtask

    initial begin
        errors = 0;
        max_cycles = 2000;

        clk = 0;
        reset = 1;
        cycle_count = 0;
        @(posedge clk); @(posedge clk);
        // lattice loader: the gauge-link matrices
        dut.dmem.mem[1006] = 32'h3F800000;
        dut.dmem.mem[1007] = 32'h00000000;
        dut.dmem.mem[1008] = 32'h00000000;
        dut.dmem.mem[1009] = 32'h00000000;
        dut.dmem.mem[1010] = 32'h00000000;
        dut.dmem.mem[1011] = 32'h00000000;
        dut.dmem.mem[1012] = 32'h00000000;
        dut.dmem.mem[1013] = 32'h00000000;
        dut.dmem.mem[1014] = 32'h3F800000;
        dut.dmem.mem[1015] = 32'h00000000;
        dut.dmem.mem[1016] = 32'h00000000;
        dut.dmem.mem[1017] = 32'h00000000;
        dut.dmem.mem[1018] = 32'h00000000;
        dut.dmem.mem[1019] = 32'h00000000;
        dut.dmem.mem[1020] = 32'h00000000;
        dut.dmem.mem[1021] = 32'h00000000;
        dut.dmem.mem[1022] = 32'h3F800000;
        dut.dmem.mem[1023] = 32'h00000000;
        dut.dmem.mem[256] = 32'h3F300303;
        dut.dmem.mem[257] = 32'hBE1D2779;
        dut.dmem.mem[258] = 32'h3ECA1B2B;
        dut.dmem.mem[259] = 32'h3BB1F8D4;
        dut.dmem.mem[260] = 32'hBE32BFA6;
        dut.dmem.mem[261] = 32'hBF103A54;
        dut.dmem.mem[262] = 32'h3E045E81;
        dut.dmem.mem[263] = 32'h3F1440AF;
        dut.dmem.mem[264] = 32'h3ECCE598;
        dut.dmem.mem[265] = 32'hBDCECAD9;
        dut.dmem.mem[266] = 32'hBF07A759;
        dut.dmem.mem[267] = 32'h3EE31F9C;
        dut.dmem.mem[268] = 32'hBDADBEB4;
        dut.dmem.mem[269] = 32'hBEC297E2;
        dut.dmem.mem[270] = 32'h3F199656;
        dut.dmem.mem[271] = 32'h3F0F6BA8;
        dut.dmem.mem[272] = 32'h3E58DA72;
        dut.dmem.mem[273] = 32'h3EB8645E;
        dut.dmem.mem[320] = 32'h3E621B5A;
        dut.dmem.mem[321] = 32'h3DA33BCD;
        dut.dmem.mem[322] = 32'h3F627E70;
        dut.dmem.mem[323] = 32'h3EA38355;
        dut.dmem.mem[324] = 32'h3E4135E6;
        dut.dmem.mem[325] = 32'hBE2061C3;
        dut.dmem.mem[326] = 32'hBDF70BA3;
        dut.dmem.mem[327] = 32'hBD32598F;
        dut.dmem.mem[328] = 32'h3E86DC03;
        dut.dmem.mem[329] = 32'h3DC2B7ED;
        dut.dmem.mem[330] = 32'hBF3B6716;
        dut.dmem.mem[331] = 32'h3F1B8F93;
        dut.dmem.mem[332] = 32'hBF68049F;
        dut.dmem.mem[333] = 32'hBEA78047;
        dut.dmem.mem[334] = 32'h3E38D32D;
        dut.dmem.mem[335] = 32'h3D856E4E;
        dut.dmem.mem[336] = 32'h3E12D79C;
        dut.dmem.mem[337] = 32'hBDF3C8BC;
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd4, "tohost (n7 = traps taken)");
            check(dut.n_bank.regs[6], 32'd3, "n6 (causes 0+0+0+3: 3 ILLEGAL, 1 PRIV)");
            check(dut.r_bank.regs[0], 32'h402127D6, "pair 0 R Re (+2.51806)");
            check(dut.r_bank.regs[1], 32'hBF94C3CC, "pair 0 R Im (-1.16223)");
            check(dut.g_bank.regs[0], 32'hBA44E600, "pair 0 G Re (-0.000751108)");
            check(dut.g_bank.regs[1], 32'h3DE343B8, "pair 0 G Im (+0.110969)");
            check(dut.b_bank.regs[0], 32'h3EACA1BC, "pair 0 B Re (+0.337171)");
            check(dut.b_bank.regs[1], 32'hBFCDF3A6, "pair 0 B Im (-1.609)");
            check(dut.r_bank.regs[2], 32'h3F000000, "pair 2 R Re (+0.5)");
            check(dut.r_bank.regs[3], 32'hBE800000, "pair 2 R Im (-0.25)");
            check(dut.g_bank.regs[2], 32'h3FE00000, "pair 2 G Re (+1.75)");
            check(dut.g_bank.regs[3], 32'h3E000000, "pair 2 G Im (+0.125)");
            check(dut.b_bank.regs[2], 32'hBF600000, "pair 2 B Re (-0.875)");
            check(dut.b_bank.regs[3], 32'h40200000, "pair 2 B Im (+2.5)");
            check(dut.r_bank.regs[4], 32'h4023A184, "pair 4 R Re (+2.55673)");
            check(dut.r_bank.regs[5], 32'hBE086754, "pair 4 R Im (-0.133207)");
            check(dut.g_bank.regs[4], 32'h3E8DD5EC, "pair 4 G Re (+0.277023)");
            check(dut.g_bank.regs[5], 32'hBFCA89E4, "pair 4 G Im (-1.58233)");
            check(dut.b_bank.regs[4], 32'hBE790A18, "pair 4 B Re (-0.243203)");
            check(dut.b_bank.regs[5], 32'h3F8CE9E6, "pair 4 B Im (+1.10089)");
            check(dut.r_bank.regs[6], 32'h3F9F13F8, "pair 6 R Re (+1.2428)");
            check(dut.r_bank.regs[7], 32'hBFED6B4E, "pair 6 R Im (-1.85484)");
            check(dut.g_bank.regs[6], 32'hBF49429E, "pair 6 G Re (-0.786173)");
            check(dut.g_bank.regs[7], 32'hBEFE679C, "pair 6 G Im (-0.496884)");
            check(dut.b_bank.regs[6], 32'h3FFD1AF8, "pair 6 B Re (+1.97739)");
            check(dut.b_bank.regs[7], 32'hBE19AB21, "pair 6 B Im (-0.150067)");
            check(n_lat, 8, "SU3MUL instructions seen");
            check(lat[0], 133, "cycles of legal SU3MUL #0");
            check(lat[1], 133, "cycles of legal SU3MUL #1");
            check(lat[2], 133, "cycles of legal SU3MUL #2");
            check(lat[3], 133, "cycles of legal SU3MUL #3");
            check(lat[4], 1, "cycles of trapping SU3MUL #0");
            check(lat[5], 1, "cycles of trapping SU3MUL #1");
            check(lat[6], 1, "cycles of trapping SU3MUL #2");
            check(lat[7], 1, "cycles of trapping SU3MUL #3");
        end

        if (errors == 0) $display("ALL AXISA SU3MUL TESTS PASSED");
        else $display("%0d AXISA SU3MUL TEST(S) FAILED", errors);
        $finish;
    end
endmodule
